import { test, expect } from '@playwright/test';

test.describe('Comment on a Record', () => {
  let recordId: string;

  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('http://localhost:3000');

    // Login if required (assuming there's a login flow)
    await page.getByRole('button', { name: /login/i }).click();
    await page.getByLabel(/email/i).fill('test@example.com');
    await page.getByLabel(/password/i).fill('password123');
    await page.getByRole('button', { name: /submit/i }).click();

    // Wait for navigation to complete
    await page.waitForURL('**/dashboard');

    // Navigate to records list
    await page.getByRole('link', { name: /records/i }).click();
    await page.waitForURL('**/records');
  });

  test('should display comment section on record detail page', async ({ page }) => {
    // Click on the first record to open its detail page
    const firstRecord = page.getByRole('link').first();
    await firstRecord.click();

    // Wait for record detail page to load
    await page.waitForURL(/\/records\/\d+/);

    // Verify comment section is visible
    const commentSection = page.getByRole('region', { name: /comments/i });
    await expect(commentSection).toBeVisible();

    // Verify comment input field exists
    const commentInput = page.getByLabel(/add comment/i);
    await expect(commentInput).toBeVisible();

    // Verify submit button exists
    const submitButton = page.getByRole('button', { name: /post comment|submit/i });
    await expect(submitButton).toBeVisible();
  });

  test('should successfully add a comment to a record', async ({ page }) => {
    // Click on the first record to open its detail page
    const firstRecord = page.getByRole('link').first();
    await firstRecord.click();

    // Wait for record detail page to load
    await page.waitForURL(/\/records\/\d+/);

    // Fill in the comment text
    const commentText = `Test comment - ${new Date().toISOString()}`;
    const commentInput = page.getByLabel(/add comment/i);
    await commentInput.fill(commentText);

    // Submit the comment
    const submitButton = page.getByRole('button', { name: /post comment|submit/i });
    await submitButton.click();

    // Wait for comment to be added (look for success message or new comment appearing)
    await page.waitForTimeout(1000);

    // Verify the comment appears in the comments list
    const commentContent = page.getByText(commentText);
    await expect(commentContent).toBeVisible();
  });

  test('should display validation error when submitting empty comment', async ({ page }) => {
    // Click on the first record to open its detail page
    const firstRecord = page.getByRole('link').first();
    await firstRecord.click();

    // Wait for record detail page to load
    await page.waitForURL(/\/records\/\d+/);

    // Try to submit without entering any text
    const submitButton = page.getByRole('button', { name: /post comment|submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/comment cannot be empty|please enter a comment/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should allow editing a previously added comment', async ({ page }) => {
    // Click on the first record to open its detail page
    const firstRecord = page.getByRole('link').first();
    await firstRecord.click();

    // Wait for record detail page to load
    await page.waitForURL(/\/records\/\d+/);

    // Add initial comment
    const initialCommentText = `Initial comment - ${new Date().toISOString()}`;
    const commentInput = page.getByLabel(/add comment/i);
    await commentInput.fill(initialCommentText);

    const submitButton = page.getByRole('button', { name: /post comment|submit/i });
    await submitButton.click();

    // Wait for comment to appear
    await page.waitForTimeout(1000);

    // Find the edit button for the comment
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await editButton.click();

    // Update the comment text
    const updatedCommentText = `Updated comment - ${new Date().toISOString()}`;
    const editInput = page.getByLabel(/edit comment/i);
    await editInput.clear();
    await editInput.fill(updatedCommentText);

    // Save the edited comment
    const saveButton = page.getByRole('button', { name: /save|update/i });
    await saveButton.click();

    // Wait for update to complete
    await page.waitForTimeout(1000);

    // Verify the updated comment is displayed
    const updatedComment = page.getByText(updatedCommentText);
    await expect(updatedComment).toBeVisible();
  });

  test('should allow deleting a comment from a record', async ({ page }) => {
    // Click on the first record to open its detail page
    const firstRecord = page.getByRole('link').first();
    await firstRecord.click();

    // Wait for record detail page to load
    await page.waitForURL(/\/records\/\d+/);

    // Add a comment to delete
    const commentToDelete = `Comment to delete - ${new Date().toISOString()}`;
    const commentInput = page.getByLabel(/add comment/i);
    await commentInput.fill(commentToDelete);

    const submitButton = page.getByRole('button', { name: /post comment|submit/i });
    await submitButton.click();

    // Wait for comment to appear
    await page.waitForTimeout(1000);

    // Find and click the delete button for the comment
    const deleteButton = page.getByRole('button', { name: /delete/i }).first();
    await deleteButton.click();

    // Confirm deletion if there's a confirmation dialog
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Wait for deletion to complete
    await page.waitForTimeout(1000);

    // Verify the comment is no longer visible
    const deletedComment = page.getByText(commentToDelete);
    await expect(deletedComment).not.toBeVisible();
  });
});
